CREATE TABLE IF NOT EXISTS settings (`key` TEXT PRIMARY KEY, `value` TEXT NOT NULL, updated_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS services (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, code TEXT NOT NULL UNIQUE, description TEXT, color TEXT DEFAULT '#2563eb', daily_limit INTEGER, avg_service_minutes INTEGER NOT NULL DEFAULT 5, active INTEGER NOT NULL DEFAULT 1, created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS counters (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, code TEXT NOT NULL UNIQUE, active INTEGER NOT NULL DEFAULT 1, created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS counter_services (counter_id INTEGER NOT NULL, service_id INTEGER NOT NULL, PRIMARY KEY(counter_id,service_id), FOREIGN KEY(counter_id) REFERENCES counters(id) ON DELETE CASCADE, FOREIGN KEY(service_id) REFERENCES services(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS users (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, username TEXT NOT NULL UNIQUE, password_hash TEXT NOT NULL, role TEXT NOT NULL DEFAULT 'operator' CHECK(role IN ('super_admin','admin','operator')), assigned_counter_id INTEGER, active INTEGER NOT NULL DEFAULT 1, created_at TEXT DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(assigned_counter_id) REFERENCES counters(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS user_services (user_id INTEGER NOT NULL, service_id INTEGER NOT NULL, PRIMARY KEY(user_id,service_id), FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE, FOREIGN KEY(service_id) REFERENCES services(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS daily_sequences (service_id INTEGER NOT NULL, queue_date TEXT NOT NULL, last_number INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(service_id,queue_date), FOREIGN KEY(service_id) REFERENCES services(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS sub_services (id INTEGER PRIMARY KEY AUTOINCREMENT, service_id INTEGER NOT NULL, name TEXT NOT NULL, description TEXT, sort_order INTEGER NOT NULL DEFAULT 0, active INTEGER NOT NULL DEFAULT 1, created_at TEXT DEFAULT CURRENT_TIMESTAMP, updated_at TEXT DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(service_id) REFERENCES services(id) ON DELETE CASCADE, UNIQUE(service_id,name));
CREATE INDEX IF NOT EXISTS idx_sub_services_picker ON sub_services(service_id,active,sort_order,name);
CREATE TABLE IF NOT EXISTS tickets (id INTEGER PRIMARY KEY AUTOINCREMENT, public_id TEXT NOT NULL UNIQUE, service_id INTEGER NOT NULL, sub_service_id INTEGER, sub_service_name TEXT, counter_id INTEGER, queue_date TEXT NOT NULL, sequence_number INTEGER NOT NULL, ticket_number TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'waiting' CHECK(status IN ('waiting','called','serving','completed','skipped','cancelled','transferred')), called_at TEXT, service_started_at TEXT, completed_at TEXT, cancel_reason TEXT, created_at TEXT DEFAULT CURRENT_TIMESTAMP, updated_at TEXT DEFAULT CURRENT_TIMESTAMP, UNIQUE(service_id,queue_date,sequence_number), FOREIGN KEY(service_id) REFERENCES services(id), FOREIGN KEY(sub_service_id) REFERENCES sub_services(id) ON DELETE SET NULL, FOREIGN KEY(counter_id) REFERENCES counters(id) ON DELETE SET NULL);
CREATE INDEX IF NOT EXISTS idx_queue ON tickets(service_id,queue_date,status,sequence_number);
CREATE INDEX IF NOT EXISTS idx_tickets_sub_service ON tickets(sub_service_id);
CREATE TRIGGER IF NOT EXISTS tickets_updated AFTER UPDATE ON tickets BEGIN UPDATE tickets SET updated_at=CURRENT_TIMESTAMP WHERE id=NEW.id; END;
CREATE TABLE IF NOT EXISTS queue_events (id INTEGER PRIMARY KEY AUTOINCREMENT, ticket_id INTEGER NOT NULL, event_type TEXT NOT NULL, counter_id INTEGER, user_id INTEGER, payload TEXT, created_at TEXT DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(ticket_id) REFERENCES tickets(id) ON DELETE CASCADE, FOREIGN KEY(counter_id) REFERENCES counters(id) ON DELETE SET NULL, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL);
CREATE INDEX IF NOT EXISTS idx_events_created ON queue_events(id,created_at);
CREATE TABLE IF NOT EXISTS audit_logs (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER, action TEXT NOT NULL, entity_type TEXT NOT NULL, entity_id INTEGER, details TEXT, ip_address TEXT, created_at TEXT DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL);
CREATE INDEX IF NOT EXISTS idx_audit_created ON audit_logs(created_at);
CREATE TABLE IF NOT EXISTS user_notification_settings (user_id INTEGER PRIMARY KEY, enabled INTEGER NOT NULL DEFAULT 1, sound_type TEXT NOT NULL DEFAULT 'chime', sound_url TEXT, volume REAL NOT NULL DEFAULT 0.80, play_mode TEXT NOT NULL DEFAULT 'auto', updated_at TEXT DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS remember_tokens (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL, selector TEXT NOT NULL UNIQUE, validator_hash TEXT NOT NULL, expires_at TEXT NOT NULL, user_agent TEXT, created_at TEXT DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE INDEX IF NOT EXISTS idx_remember_expiry ON remember_tokens(expires_at);
CREATE TABLE IF NOT EXISTS online_registrations (id INTEGER PRIMARY KEY AUTOINCREMENT, public_id TEXT NOT NULL UNIQUE, registration_code TEXT NOT NULL UNIQUE, service_id INTEGER NOT NULL, ticket_id INTEGER UNIQUE, visitor_name TEXT NOT NULL, phone TEXT, email TEXT, identity_number TEXT, notes TEXT, visit_date TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'registered', source TEXT NOT NULL DEFAULT 'native_form', consent_at TEXT NOT NULL, checked_in_at TEXT, created_at TEXT DEFAULT CURRENT_TIMESTAMP, updated_at TEXT DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(service_id) REFERENCES services(id), FOREIGN KEY(ticket_id) REFERENCES tickets(id) ON DELETE SET NULL);
CREATE INDEX IF NOT EXISTS idx_registration_visit ON online_registrations(service_id,visit_date,status);
CREATE INDEX IF NOT EXISTS idx_registration_phone ON online_registrations(phone);
CREATE TABLE IF NOT EXISTS api_clients (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, key_hash TEXT NOT NULL UNIQUE, allowed_origin TEXT, active INTEGER NOT NULL DEFAULT 1, last_used_at TEXT, created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS api_rate_limits (client_key TEXT NOT NULL, window_start TEXT NOT NULL, request_count INTEGER NOT NULL DEFAULT 1, PRIMARY KEY(client_key,window_start));
CREATE TABLE IF NOT EXISTS notification_devices (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL, device_id TEXT NOT NULL, device_name TEXT NOT NULL, token_hash TEXT NOT NULL UNIQUE, last_used_at TEXT, expires_at TEXT NOT NULL, created_at TEXT DEFAULT CURRENT_TIMESTAMP, UNIQUE(user_id,device_id), FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE INDEX IF NOT EXISTS idx_notification_device_expiry ON notification_devices(expires_at);
